c.cpp:
class Solution {
public:
    vector<string> splitWordsBySeparator(vector<string>& words, char separator) {
        vector<string> ans;
        for (auto& w : words) {
            string cur;
            for (char c : w) {
                if (c == separator) { if (!cur.empty()) ans.push_back(cur); cur.clear(); }
                else cur += c;
            }
            if (!cur.empty()) ans.push_back(cur);
        }
        return ans;
    }
};

c.java:
class Solution {
    public List<String> splitWordsBySeparator(List<String> words, char separator) {
        List<String> ans = new ArrayList<>();
        for (String w : words)
            for (String p : w.split("\\" + Character.toString(separator), -1))
                if (!p.isEmpty()) ans.add(p);
        return ans;
    }
}

